    /// <summary>
    /// The Amazon Resource Name (ARN) of an IAM role that Amazon SageMaker AI can assume to perform actions on your behalf. For more informa- tion, see SageMaker AI Roles . NOTE: To be able to pass this role to Amazon SageMaker AI, the caller of this action must have the iam:PassRole permission. Constraints: o min: 20 o max: 2048 o pattern: arn:aws[a-z\-]*:iam::\d{12}:role/?[a-zA-Z_0-9+=,.@\-_/]+
    /// </summary>
    [CliOption("--execution-role-arn")]
    public string? ExecutionRoleArn { get; set; }

    /// <summary>
    /// Specifies an Amazon Virtual Private Cloud (VPC) that your SageMaker jobs, hosted models, and compute resources have access to. You can control access to and from your resources by configuring a VPC. For more information, see Give SageMaker Access to Resources in your Amazon VPC . SecurityGroupIds -&gt; (list) [required] The VPC security group IDs, in the form sg-xxxxxxxx . Specify the security groups for the VPC that is specified in the Subnets field. Constraints: o min: 1 o max: 5 (string) Constraints: o min: 0 o max: 32 o pattern: [-0-9a-zA-Z]+ Subnets -&gt; (list) [required] The ID of the subnets in the VPC to which you want to connect your training job or model. For information about the availabil- ity of specific instance types, see Supported Instance Types and Availability Zones . Constraints: o min: 1 o max: 16 (string) Constraints: o min: 0 o max: 32 o pattern: [-0-9a-zA-Z]+ Shorthand Syntax: SecurityGroupIds=string,string,Subnets=string,string JSON Syntax: { "SecurityGroupIds": ["string", ...], "Subnets": ["string", ...] }
    /// </summary>
    [CliOption("--vpc-config")]
    public string? VpcConfig { get; set; }

    [CliFlag("--enable-network-isolation")]
    public bool? EnableNetworkIsolation { get; set; }

    /// <summary>
    /// The configuration parameters for utilization metrics. EnableEnhancedMetrics -&gt; (boolean) Specifies whether to enable enhanced metrics for the endpoint. Enhanced metrics provide utilization and invocation data at in- stance and container granularity. Container granularity is sup- ported for Inference Components. The default is False . EnableDetailedObservability -&gt; (boolean) Indicates whether detailed observability is enabled for the end- point. When set to True , the following metrics are published at the configured frequency: o Container-level inference metrics scraped from the container's Prometheus endpoint (such as request latency, error counts, and throughput). Available metrics vary by framework. o Per-GPU metrics (utilization, memory, and temperature) attrib- uted to individual inference components. o Per-instance host metrics (CPU, memory, and disk utilization). o Inference component placement metrics (copy count per Avail- ability Zone). For first-party and Deep Learning Containers (DLC), the Prometheus endpoint path is determined automatically. For Bring-Your-Own-Container (BYOC) cases, you can optionally set ContainerMetricsConfig to specify a custom endpoint path. If not specified, the default path /metrics on port 8080 is used. When set to False , these additional metrics are not published. Standard invocation and utilization metrics controlled by En- ableEnhancedMetrics are unaffected. The default value for new endpoint configurations is True . For existing endpoint configurations created before this feature, the value is False unless explicitly set. MetricPublishFrequencyInSeconds -&gt; (integer) The interval, in seconds, at which metrics are published to Ama- zon CloudWatch. Defaults to 60 . Valid values: 10 , 30 , 60 , 120 , 180 , 240 , 300 . When EnableEnhancedMetrics is set to False , this interval ap- plies to utilization metrics only. Invocation metrics continue to be published at the default 60-second interval. When En- ableEnhancedMetrics is set to True , this interval applies to both utilization and invocation metrics. When EnableDetailedObservability is set to True , this interval applies to per-GPU metrics, per-instance host metrics, container metrics, and fleet-level inference component lifecycle and placement metrics. Shorthand Syntax: EnableEnhancedMetrics=boolean,EnableDetailedObservability=boolean,MetricPublishFrequencyInSeconds=integer JSON Syntax: { "EnableEnhancedMetrics": true|false, "EnableDetailedObservability": true|false, "MetricPublishFrequencyInSeconds": integer }
    /// </summary>
    [CliOption("--metrics-config")]
    public string? MetricsConfig { get; set; }

    [CliFlag("--cli-input-json")]
    public bool? CliInputJson { get; set; }

    [CliFlag("--generate-cli-skeleton")]
    public bool? GenerateCliSkeleton { get; set; }

